# ============================================================== md5sum
GUIDES.append(dict(
    name="md5sum", section="1", one_line="compute and check MD5 message digests",
    plain=["`md5sum` turns a file (or text) into a 32-character fingerprint. The same input always gives the same fingerprint; change one byte and the fingerprint changes completely.",
           "Use it to check that a download was not corrupted, or that two files are identical. MD5 is broken for security (an attacker can build two different files with one MD5), so do not use it to trust a file. In CTFs it is often the format of a hash you must crack."],
    when=["Compare two files quickly.", "Verify a downloaded file against a published checksum.", "Make an MD5 of a string to test a hash cracker.", "Check a list of files from a checksum file."],
    examples=[("Hash a file", "md5sum notes.txt", "Prints the fingerprint and the file name."),
              ("Hash a piece of text", "echo -n 'password' | md5sum", "echo -n leaves out the newline. Without -n the result is different, which is a very common mistake when you test a hash."),
              ("Write a checksum list and verify it", "md5sum *.iso > SUMS.md5\nmd5sum -c SUMS.md5", "The first line records the hashes. -c reads the list and prints OK or FAILED for each file."),
              ("Only show failures", "md5sum -c --quiet SUMS.md5", "--quiet hides the OK lines so you see only problems."),
              ("Are two files identical?", "md5sum a.bin b.bin", "Same fingerprint, same content (for practical purposes)."),
              ("Find duplicate files", "find . -type f -exec md5sum {} + | sort | uniq -w32 -d", "Hashes every file, sorts, and prints lines whose first 32 characters repeat: duplicates.")],
    options=[
        ("-b, --binary", "Read in binary mode (the default on Linux).", "Cross-platform checks."),
        ("-t, --text", "Read in text mode.", "Windows line endings."),
        ("-c, --check", "Read sums from a file and check them.", "Verifying downloads."),
        ("--tag", "Print in BSD style: MD5 (file) = hash.", "Compatibility."),
        ("-z, --zero", "End output lines with NUL, not newline.", "File names with newlines."),
        ("--ignore-missing", "With -c, ignore missing files.", "Partial downloads."),
        ("--quiet", "With -c, do not print OK lines.", "Short reports."),
        ("--status", "With -c, print nothing; use the exit status.", "Scripts."),
        ("--strict", "With -c, fail on badly formatted lines.", "Strict checks."),
        ("-w, --warn", "Warn about badly formatted lines.", "Debugging a SUMS file."),
        ("--help", "Show help.", "A reminder."),
        ("--version", "Show version.", "Check install.")],
    mistakes=["Forgetting echo -n: the newline changes the hash.", "Trusting MD5 for security.", "Comparing the hash by eye: use md5sum -c or diff.", "Running md5sum on a directory: it only handles files."],
    try_=["Hash 'password' with and without echo -n and compare.", "Crack that MD5 with john or hashcat.", "Modify one character in a file and watch the hash change completely."],
    see_also="sha256sum(1), sha1sum(1), cksum(1), openssl(1) (openssl dgst), john(8), hashcat(1)."))

# ============================================================== sha256sum
